import {useMemo,useState} from 'react';
import {Alert,Pressable,Share,StyleSheet,Text,View} from '@/platform/react-native';
import {useMutation,useQuery,useQueryClient} from '@tanstack/react-query';
import {router} from '@/router';
import {Ionicons} from '@/platform/icons';
import {api} from '@/lib/api';
import {useAuth} from '@/store/auth';
import {Avatar,Muted,Screen,TabBar,useAppTheme} from '@/components/UI';
import {LinkText} from '@/components/LinkText';

type FeedFilter='All Posts'|'Announcements'|'Events';

export default function Home(){
 const{palette}=useAppTheme();const user=useAuth(s=>s.user);const qc=useQueryClient();const[filter,setFilter]=useState<FeedFilter>('All Posts');
 const activity=useQuery<any[]>({queryKey:['personal-activity'],queryFn:async()=>(await api.get('/me/activity')).data});
 const posts=useMemo(()=>{const all=activity.data??[];if(filter==='Announcements')return all.filter(x=>x.IsAnnouncement);if(filter==='Events')return all.filter(x=>String(x.PostType).toUpperCase()==='EVENT');return all},[activity.data,filter]);
 const interact=useMutation({mutationFn:async({id,action}:{id:string;action:'like'|'save'|'share'})=>(await api.post(action==='like'?`/posts/${id}/reaction`:`/posts/${id}/${action}`,action==='like'?{reaction:'LIKE'}:undefined)).data,onSuccess:()=>qc.invalidateQueries({queryKey:['personal-activity']}),onError:(e:any)=>Alert.alert('Action failed',e.response?.data?.error??'Please try again.')});
 const go=(path:string)=>router.push(path as any);
 async function sharePost(post:any){try{await interact.mutateAsync({id:post.Id,action:'share'});await Share.share({message:post.Body})}catch{}}
 return <Screen scroll contentStyle={s.page}>
  <SectionHeader title="Community Feed"/>
  <TabBar value={filter} onChange={setFilter} items={[{key:'All Posts',label:'All Posts'},{key:'Announcements',label:'Announcements',icon:'megaphone-outline'},{key:'Events',label:'Events',icon:'calendar-outline'}]}/>
  {posts.length?posts.slice(0,8).map((post:any)=>{const profileImage=post.ProfileImage||(post.CreatedBy===user?.Id?user?.ProfileImage:undefined);return <View key={post.Id} style={[s.post,{backgroundColor:palette.surface,borderColor:palette.border}]}><View style={s.postHead}><Avatar name={`${post.FirstName||''} ${post.LastName||''}`} uri={profileImage} size={46}/><View style={{flex:1}}><Text style={[s.author,{color:palette.text}]}>{post.FirstName} {post.LastName}</Text><Muted>{post.CommunityName} · {timeAgo(post.CreatedAt)}</Muted></View>{post.IsAnnouncement?<View style={[s.pinned,{backgroundColor:palette.primarySoft}]}><Ionicons name="megaphone" size={14} color={palette.primary}/><Text style={[s.pinnedText,{color:palette.primary}]}>Announcement</Text></View>:null}</View><Pressable onPress={()=>go(`/community/${post.CommunityId}/post/${post.Id}`)}><LinkText style={[s.postBody,{color:palette.text}]}>{post.Body}</LinkText></Pressable><View style={[s.postActions,{borderTopColor:palette.border}]}><Pressable accessibilityLabel="Like post" onPress={()=>interact.mutate({id:post.Id,action:'like'})} style={s.postAction}><Ionicons name="heart-outline" size={20} color={palette.danger}/><Text style={[s.count,{color:palette.text}]}>{post.ReactionCount||0}</Text></Pressable><Pressable accessibilityLabel="Open post comments" onPress={()=>go(`/community/${post.CommunityId}/post/${post.Id}`)} style={s.postAction}><Ionicons name="chatbubble-outline" size={20} color={palette.text}/><Text style={[s.count,{color:palette.text}]}>{post.CommentCount||0}</Text></Pressable><Pressable accessibilityLabel="Share post" onPress={()=>sharePost(post)} style={s.postAction}><Ionicons name="share-outline" size={20} color={palette.text}/></Pressable><Pressable accessibilityLabel="Save post" onPress={()=>interact.mutate({id:post.Id,action:'save'})} style={[s.postAction,{marginLeft:'auto'}]}><Ionicons name="bookmark-outline" size={20} color={palette.text}/></Pressable></View></View>}):<View style={[s.empty,{backgroundColor:palette.surface,borderColor:palette.border}]}><Text style={[s.emptyTitle,{color:palette.text}]}>Your community feed</Text><Muted>Posts from your communities will appear here.</Muted></View>}
 </Screen>
}

function SectionHeader({title}:{title:string}){const{palette}=useAppTheme();return <View style={s.section}><Text style={[s.sectionTitle,{color:palette.text}]}>{title}</Text></View>}
function timeAgo(value:string){const minutes=Math.max(1,Math.floor((Date.now()-new Date(value).getTime())/60000));if(minutes<60)return `${minutes}m ago`;const hours=Math.floor(minutes/60);if(hours<24)return `${hours}h ago`;return `${Math.floor(hours/24)}d ago`}

const s=StyleSheet.create({page:{paddingTop:0,paddingHorizontal:16,paddingBottom:90},header:{minHeight:88,flexDirection:'row',alignItems:'center',justifyContent:'space-between'},brand:{flexDirection:'row',alignItems:'center',gap:8,flexShrink:1},logoFrame:{width:58,height:58,borderRadius:14,overflow:'hidden'},logo:{width:'100%',height:'100%',transform:[{scale:1.45}]},brandName:{fontSize:18,fontWeight:'900',color:'#08723A'},tagline:{fontSize:9,color:'#64748B',marginTop:3},headerActions:{flexDirection:'row',alignItems:'center',gap:8},headerButton:{width:44,height:44,alignItems:'center',justifyContent:'center'},badge:{position:'absolute',right:1,top:0,minWidth:19,height:19,borderRadius:10,backgroundColor:'#EF4444',alignItems:'center',justifyContent:'center'},badgeText:{fontSize:10,fontWeight:'900',color:'#fff'},searchArea:{zIndex:5},search:{minHeight:58,borderRadius:29,borderWidth:1,borderColor:'#E2E8F0',backgroundColor:'#fff',paddingHorizontal:18,flexDirection:'row',alignItems:'center',gap:12,shadowColor:'#11243F',shadowOpacity:.06,shadowRadius:10,elevation:2},searchInput:{flex:1,minWidth:0,fontSize:15,color:'#11243F'},searchResults:{position:'absolute',top:64,left:0,right:0,borderRadius:14,borderWidth:1,borderColor:'#E2E8F0',backgroundColor:'#fff',padding:10,shadowColor:'#11243F',shadowOpacity:.15,shadowRadius:15,elevation:12},searchRow:{minHeight:52,flexDirection:'row',alignItems:'center',gap:10,borderBottomWidth:1,borderBottomColor:'#E2E8F0'},searchName:{flex:1,fontWeight:'800',color:'#11243F'},quickRow:{gap:18,paddingVertical:25},quick:{width:68,alignItems:'center',gap:8},quickIcon:{width:58,height:58,borderRadius:17,borderWidth:1,borderColor:'#E2E8F0',backgroundColor:'#fff',alignItems:'center',justifyContent:'center'},quickText:{fontSize:11,fontWeight:'700',textAlign:'center',color:'#11243F'},smallBadge:{position:'absolute',right:-5,top:-7,minWidth:19,height:19,borderRadius:10,backgroundColor:'#0F8A43',alignItems:'center',justifyContent:'center'},smallBadgeText:{fontSize:10,color:'#fff',fontWeight:'900'},section:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginTop:5,marginBottom:14},sectionTitle:{fontSize:21,fontWeight:'900',color:'#11243F'},sectionLink:{flexDirection:'row',alignItems:'center'},sectionLinkText:{fontSize:14,fontWeight:'800',color:'#0F8A43'},communityRow:{gap:14,paddingBottom:26},communityCard:{width:172,borderRadius:15,borderWidth:1,borderColor:'#E2E8F0',backgroundColor:'#fff',overflow:'hidden'},communityImage:{height:100,alignItems:'center',justifyContent:'center',overflow:'hidden'},role:{position:'absolute',left:9,top:9,backgroundColor:'#0F8A43',borderRadius:8,paddingHorizontal:9,paddingVertical:4},roleText:{fontSize:11,fontWeight:'800',color:'#fff'},communityBody:{padding:12},communityName:{minHeight:42,fontSize:15,fontWeight:'900',lineHeight:20,color:'#11243F'},members:{fontSize:11,color:'#0F8A43',marginTop:6},filters:{borderWidth:1,borderColor:'#E2E8F0',borderRadius:14,overflow:'hidden',marginBottom:14},filter:{minWidth:112,minHeight:48,alignItems:'center',justifyContent:'center',paddingHorizontal:16},filterActive:{backgroundColor:'#0F8A43'},filterText:{fontSize:13,fontWeight:'700',color:'#11243F'},filterTextActive:{color:'#fff'},post:{borderWidth:1,borderColor:'#E2E8F0',borderRadius:17,backgroundColor:'#fff',padding:16,marginBottom:14},postHead:{flexDirection:'row',alignItems:'center',gap:11},author:{fontSize:15,fontWeight:'900',color:'#11243F'},pinned:{flexDirection:'row',gap:5,backgroundColor:'#FFFFFF',borderRadius:8,padding:7},pinnedText:{fontSize:10,fontWeight:'800',color:'#0F8A43'},postBody:{fontSize:15,lineHeight:23,color:'#11243F',marginVertical:17},postActions:{borderTopWidth:1,borderTopColor:'#E2E8F0',paddingTop:13,flexDirection:'row',alignItems:'center',gap:22},postAction:{minWidth:38,minHeight:34,flexDirection:'row',alignItems:'center',gap:6},count:{fontSize:13,fontWeight:'700',color:'#11243F'},empty:{borderWidth:1,borderColor:'#E2E8F0',borderRadius:16,padding:22,marginBottom:22},emptyTitle:{fontSize:17,fontWeight:'900',color:'#11243F',marginBottom:4},fab:{position:'absolute',right:20,bottom:96,width:62,height:62,borderRadius:31,backgroundColor:'#0F8A43',alignItems:'center',justifyContent:'center',shadowColor:'#08723A',shadowOpacity:.25,shadowRadius:12,elevation:6},modalBackdrop:{flex:1,backgroundColor:'rgba(15,31,68,.35)',justifyContent:'flex-end'},picker:{maxHeight:'72%',backgroundColor:'#fff',borderTopLeftRadius:24,borderTopRightRadius:24,padding:20},pickerHead:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginBottom:12},pickerTitle:{fontSize:20,fontWeight:'900',color:'#11243F'},pickerRow:{minHeight:58,flexDirection:'row',alignItems:'center',gap:12,borderBottomWidth:1,borderBottomColor:'#E2E8F0'},pickerText:{flex:1,fontSize:15,fontWeight:'800',color:'#11243F'}});
